class SimpleDataset:
    """An indexable collection of rows with a useful repr."""
    def __init__(self, rows: list[dict]):
        self.rows = rows
    def __len__(self) -> int:
        return len(self.rows)
    def __getitem__(self, i):
        return self.rows[i]
    def __repr__(self) -> str:
        return f'SimpleDataset(rows={len(self)})'

if __name__ == '__main__':
    ds = SimpleDataset([{'x': 1}, {'x': 2}])
    print(ds, ds[0])

notes.body:
OOP is a means, not a virtue — this module will not make you a software architect, and deep inheritance trees are a liability, not a skill. The honest takeaway is narrower: read and write classes with clean contracts, because every ML library you'll touch is built that way. Environment hygiene (one venv per project, pinned requirements) is the part of this module that will save you the most real hours.

